"""DID proof-of-possession JWT helpers."""

from __future__ import annotations

import hashlib
import time
import uuid
from dataclasses import dataclass
from typing import Any

import jwt
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

from authsome.identity.keys import public_key_from_did_key

POP_AUTH_SCHEME = "PoP"
DEFAULT_AUDIENCE = "authsome-daemon"
DEFAULT_TTL_SECONDS = 60


class ProofValidationError(ValueError):
    """Raised when a PoP JWT is missing, malformed, or not request-bound."""


@dataclass(frozen=True)
class ProofClaims:
    issuer: str
    subject: str
    expires_at: int
    jwt_id: str


class ReplayCache:
    """Small in-memory jti replay cache."""

    def __init__(self) -> None:
        self._seen: dict[str, int] = {}

    def check_and_store(self, jti: str, exp: int) -> None:
        now = int(time.time())
        self._seen = {key: value for key, value in self._seen.items() if value > now}
        if jti in self._seen:
            raise ProofValidationError("Proof JWT was already used")
        self._seen[jti] = exp


def body_sha256(body: bytes) -> str:
    return hashlib.sha256(body).hexdigest()


def create_proof_jwt(
    *,
    private_key: Ed25519PrivateKey,
    issuer: str,
    subject: str,
    method: str,
    path_query: str,
    body: bytes,
    audience: str = DEFAULT_AUDIENCE,
    ttl_seconds: int = DEFAULT_TTL_SECONDS,
) -> str:
    now = int(time.time())
    payload = {
        "iss": issuer,
        "sub": subject,
        "aud": audience,
        "iat": now,
        "exp": now + ttl_seconds,
        "jti": str(uuid.uuid4()),
        "htm": method.upper(),
        "htu": path_query,
        "body_sha256": body_sha256(body),
    }
    return jwt.encode(payload, private_key, algorithm="EdDSA")


def validate_proof_jwt(
    *,
    token: str,
    method: str,
    path_query: str,
    body: bytes,
    replay_cache: ReplayCache | None = None,
    audience: str = DEFAULT_AUDIENCE,
) -> ProofClaims:
    unverified = _unverified_claims(token)
    issuer = _required_str(unverified, "iss")
    public_key = public_key_from_did_key(issuer)
    try:
        claims = jwt.decode(token, public_key, algorithms=["EdDSA"], audience=audience)
    except jwt.PyJWTError as exc:
        raise ProofValidationError(f"Invalid proof JWT: {exc}") from exc

    if _required_str(claims, "htm").upper() != method.upper():
        raise ProofValidationError("Proof JWT method does not match request")
    if _required_str(claims, "htu") != path_query:
        raise ProofValidationError("Proof JWT URL does not match request")
    if _required_str(claims, "body_sha256") != body_sha256(body):
        raise ProofValidationError("Proof JWT body hash does not match request")

    subject = _required_str(claims, "sub")
    jwt_id = _required_str(claims, "jti")
    exp = claims.get("exp")
    if not isinstance(exp, int):
        raise ProofValidationError("Proof JWT exp must be an integer")
    if replay_cache is not None:
        replay_cache.check_and_store(jwt_id, exp)
    return ProofClaims(issuer=issuer, subject=subject, expires_at=exp, jwt_id=jwt_id)


def _unverified_claims(token: str) -> dict[str, Any]:
    try:
        claims = jwt.decode(token, options={"verify_signature": False})
    except jwt.PyJWTError as exc:
        raise ProofValidationError(f"Malformed proof JWT: {exc}") from exc
    if not isinstance(claims, dict):
        raise ProofValidationError("Proof JWT claims must be an object")
    return claims


def _required_str(claims: dict[str, Any], name: str) -> str:
    value = claims.get(name)
    if not isinstance(value, str) or not value:
        raise ProofValidationError(f"Proof JWT missing string claim: {name}")
    return value

"""Server-owned identity registry."""

from __future__ import annotations

import json
import os
from datetime import UTC, datetime
from pathlib import Path

from pydantic import BaseModel, Field

from authsome.identity.keys import public_key_from_did_key, validate_handle


class IdentityRegistration(BaseModel):
    """Registered identity binding stored by the daemon."""

    handle: str
    did: str
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))


class IdentityRegistrationError(ValueError):
    """Raised when an identity registration conflicts with existing registry state."""


class IdentityRegistry:
    """JSON-backed authoritative registry for daemon identity handles."""

    def __init__(self, server_home: Path) -> None:
        self._path = server_home / "identity_registry.json"

    def register(self, *, handle: str, did: str) -> IdentityRegistration:
        """Register a handle/DID binding, idempotent only for the same pair."""
        handle = validate_handle(handle)
        public_key_from_did_key(did)

        entries = self._load()
        existing = entries.get(handle)
        if existing is not None:
            registration = IdentityRegistration.model_validate(existing)
            if registration.did == did:
                return registration
            raise IdentityRegistrationError(f"Identity handle '{handle}' is already registered")

        for registered_handle, raw in entries.items():
            registration = IdentityRegistration.model_validate(raw)
            if registration.did == did:
                raise IdentityRegistrationError(f"DID is already registered to identity handle '{registered_handle}'")

        now = datetime.now(UTC)
        registration = IdentityRegistration(handle=handle, did=did, created_at=now, updated_at=now)
        entries[handle] = registration.model_dump(mode="json")
        self._save(entries)
        return registration

    def resolve(self, handle: str) -> IdentityRegistration | None:
        entries = self._load()
        raw = entries.get(handle)
        if raw is None:
            return None
        return IdentityRegistration.model_validate(raw)

    def _load(self) -> dict[str, dict[str, object]]:
        try:
            data = json.loads(self._path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return {}
        if not isinstance(data, dict):
            return {}
        return {str(key): value for key, value in data.items() if isinstance(value, dict)}

    def _save(self, entries: dict[str, dict[str, object]]) -> None:
        self._path.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = self._path.with_suffix(".json.tmp")
        tmp_path.write_text(json.dumps(entries, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        os.replace(tmp_path, self._path)

"""Local identity files and did:key helpers."""

from __future__ import annotations

import os
import random
import re
from datetime import UTC, datetime
from pathlib import Path

import base58
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey
from pydantic import BaseModel, Field

_ED25519_MULTICODEC_PREFIX = b"\xed\x01"
_DID_KEY_PREFIX = "did:key:z"
_HANDLE_RE = re.compile(r"^[a-z0-9][a-z0-9-]*[a-z0-9]$")

_ADJECTIVES = (
    "brisk",
    "calm",
    "clear",
    "eager",
    "fresh",
    "gentle",
    "honest",
    "kind",
    "lively",
    "quiet",
    "rapid",
    "steady",
    "swift",
    "vivid",
)
_ADVERBS = (
    "boldly",
    "brightly",
    "clearly",
    "deeply",
    "easily",
    "firmly",
    "gladly",
    "lightly",
    "quickly",
    "smoothly",
    "warmly",
    "wisely",
)


class IdentityMetadata(BaseModel):
    """Local identity metadata stored beside the caller private key."""

    handle: str
    did: str
    name: str | None = None
    description: str | None = None
    owner_email: str | None = None
    registered: bool = False
    registration_status: str = "local"
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))

    model_config = {"extra": "allow"}


def identities_dir(home: Path) -> Path:
    return home / "identities"


def identity_metadata_path(home: Path, handle: str) -> Path:
    return identities_dir(home) / f"{handle}.json"


def identity_key_path(home: Path, handle: str) -> Path:
    return identities_dir(home) / f"{handle}.key"


def generate_handle() -> str:
    """Generate a human-readable identity handle."""
    return "-".join(
        (
            random.choice(_ADJECTIVES),
            random.choice(_ADVERBS),
            random.choice(_ADVERBS),
            f"{random.SystemRandom().randint(0, 9999):04d}",
        )
    )


def validate_handle(handle: str) -> str:
    if not _HANDLE_RE.match(handle):
        raise ValueError(f"Invalid identity handle: {handle}")
    return handle


def public_key_to_did_key(public_key: Ed25519PublicKey) -> str:
    raw = public_key.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw,
    )
    return _DID_KEY_PREFIX + base58.b58encode(_ED25519_MULTICODEC_PREFIX + raw).decode("ascii")


def public_key_from_did_key(did: str) -> Ed25519PublicKey:
    if not did.startswith(_DID_KEY_PREFIX):
        raise ValueError("Only did:key Ed25519 identifiers are supported")
    try:
        decoded = base58.b58decode(did[len(_DID_KEY_PREFIX) :])
    except ValueError as exc:
        raise ValueError("Malformed did:key value") from exc
    if not decoded.startswith(_ED25519_MULTICODEC_PREFIX):
        raise ValueError("did:key does not use the Ed25519 multicodec prefix")
    raw_key = decoded[len(_ED25519_MULTICODEC_PREFIX) :]
    if len(raw_key) != 32:
        raise ValueError("Ed25519 did:key public key must be 32 bytes")
    return Ed25519PublicKey.from_public_bytes(raw_key)


def private_key_to_hex(private_key: Ed25519PrivateKey) -> str:
    raw = private_key.private_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PrivateFormat.Raw,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return raw.hex()


def private_key_from_hex(value: str) -> Ed25519PrivateKey:
    try:
        raw = bytes.fromhex(value.strip())
    except ValueError as exc:
        raise ValueError("Malformed Ed25519 private key hex") from exc
    if len(raw) != 32:
        raise ValueError("Ed25519 private key must be 32 bytes")
    return Ed25519PrivateKey.from_private_bytes(raw)


def load_private_key(home: Path, handle: str) -> Ed25519PrivateKey:
    return private_key_from_hex(identity_key_path(home, handle).read_text(encoding="utf-8"))


def load_identity(home: Path, handle: str) -> IdentityMetadata:
    return IdentityMetadata.model_validate_json(identity_metadata_path(home, handle).read_text(encoding="utf-8"))


def identity_exists(home: Path, handle: str) -> bool:
    return identity_metadata_path(home, handle).exists() and identity_key_path(home, handle).exists()


def create_identity(home: Path, handle: str | None = None) -> IdentityMetadata:
    """Create a local identity and private key, returning existing metadata if present."""
    resolved_handle = validate_handle(handle or _unique_handle(home))
    if identity_exists(home, resolved_handle):
        return load_identity(home, resolved_handle)

    directory = identities_dir(home)
    directory.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(directory, 0o700)
    except OSError:
        pass

    private_key = Ed25519PrivateKey.generate()
    did = public_key_to_did_key(private_key.public_key())
    now = datetime.now(UTC)
    metadata = IdentityMetadata(
        handle=resolved_handle,
        did=did,
        name=resolved_handle,
        created_at=now,
        updated_at=now,
    )

    key_path = identity_key_path(home, resolved_handle)
    metadata_path = identity_metadata_path(home, resolved_handle)
    key_path.write_text(private_key_to_hex(private_key) + "\n", encoding="utf-8")
    try:
        os.chmod(key_path, 0o600)
    except OSError:
        pass
    metadata_path.write_text(metadata.model_dump_json(indent=2), encoding="utf-8")
    return metadata


def remove_legacy_default_identity(home: Path) -> None:
    """Remove legacy local files for the implicit default identity."""
    for path in (identity_metadata_path(home, "default"), identity_key_path(home, "default")):
        try:
            path.unlink()
        except FileNotFoundError:
            pass


def ensure_local_identity(home: Path) -> IdentityMetadata:
    """Ensure a non-default local identity exists."""
    remove_legacy_default_identity(home)
    directory = identities_dir(home)
    if directory.exists():
        for metadata_path in sorted(directory.glob("*.json")):
            handle = metadata_path.stem
            if handle != "default" and identity_exists(home, handle):
                return load_identity(home, handle)
    return create_identity(home)


def _unique_handle(home: Path) -> str:
    for _ in range(100):
        handle = generate_handle()
        if not identity_exists(home, handle):
            return handle
    raise RuntimeError("Unable to generate a unique identity handle")

"""Identity registration routes."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException, Request
from pydantic import BaseModel

from authsome.identity.registry import IdentityRegistrationError

router = APIRouter(prefix="/identities", tags=["identities"])


class RegisterIdentityRequest(BaseModel):
    handle: str
    did: str


@router.post("/register")
async def register_identity(body: RegisterIdentityRequest, request: Request) -> dict[str, str]:
    try:
        registration = request.app.state.identity_registry.register(handle=body.handle, did=body.did)
    except IdentityRegistrationError:
        raise
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {
        "status": "registered",
        "identity": registration.handle,
        "did": registration.did,
    }

"""Global configuration models."""

from __future__ import annotations

from importlib.metadata import PackageNotFoundError, version
from typing import Any

from pydantic import BaseModel, Field


def current_spec_version() -> int:
    """Return the config spec version derived from authsome's minor package version."""
    try:
        package_version = version("authsome")
    except PackageNotFoundError:
        return 0
    parts = package_version.split(".")
    if len(parts) < 2:
        return 0
    try:
        return int(parts[1])
    except ValueError:
        return 0


class EncryptionConfig(BaseModel):
    """
    Encryption configuration block.

    Modes:
    - "local_key": master key stored at ~/.authsome/server/master.key
    - "keyring":   master key stored in the OS keyring
    """

    mode: str = "local_key"


class GlobalConfig(BaseModel):
    """Global configuration for the local Authsome install."""

    spec_version: int = Field(default_factory=current_spec_version)
    encryption: EncryptionConfig | None = Field(default_factory=EncryptionConfig)

    extra_fields: dict[str, Any] = Field(default_factory=dict, exclude=True)

    model_config = {"extra": "allow"}

"""FastAPI dependency helpers."""

from __future__ import annotations

from fastapi import HTTPException, Request

from authsome.auth import AuthService
from authsome.auth.sessions import AuthSessionStore
from authsome.identity.proof import POP_AUTH_SCHEME, ProofValidationError, validate_proof_jwt


def get_auth_service(request: Request) -> AuthService:
    return request.app.state.auth_service


def get_auth_service_for_identity(request: Request, identity: str) -> AuthService:
    return AuthService(vault=request.app.state.vault, identity=identity)


async def get_protected_auth_service(request: Request) -> AuthService:
    authorization = request.headers.get("Authorization")
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing PoP authorization header")
    scheme, _, token = authorization.partition(" ")
    if scheme != POP_AUTH_SCHEME or not token:
        raise HTTPException(status_code=401, detail="Expected Authorization: PoP <jwt>")

    body = await request.body()
    path_query = request.url.path
    if request.url.query:
        path_query = f"{path_query}?{request.url.query}"
    try:
        claims = validate_proof_jwt(
            token=token,
            method=request.method,
            path_query=path_query,
            body=body,
            replay_cache=request.app.state.proof_replay_cache,
        )
    except (ProofValidationError, ValueError) as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from exc

    registration = request.app.state.identity_registry.resolve(claims.subject)
    if registration is None:
        raise HTTPException(status_code=401, detail="Unknown identity handle")
    if registration.did != claims.issuer:
        raise HTTPException(status_code=401, detail="Identity issuer does not match registered DID")

    request.state.identity = claims.subject
    request.state.did = claims.issuer
    request.state.registration_status = "registered"
    return get_auth_service_for_identity(request, claims.subject)


def get_auth_sessions(request: Request) -> AuthSessionStore:
    return request.app.state.auth_sessions


def get_server_base_url(request: Request) -> str:
    return request.app.state.server_base_url

